window.S17Page={"sceneId":"c2","caseId":"s17x-c2-cement-displacement","name":"注水泥参数优化","title":"注水泥参数优化","summary":"把置换效率和环空压力放在同一张候选图上，观察压力上限怎样改变可选排量与浆体密度。","directory":"expansion-cases","caseVersion":"1.2.1","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){'use strict';
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));const sum=a=>a.reduce((s,x)=>s+x,0),mean=a=>a.length?sum(a)/a.length:0;
function rng(seed){let s=seed>>>0;return ()=>{s=(1664525*s+1013904223)>>>0;return s/4294967296}}
function solve(A,b){A=A.map((r,i)=>r.slice().concat(b[i]));const n=b.length;for(let j=0;j<n;j++){let p=j;for(let i=j+1;i<n;i++)if(Math.abs(A[i][j])>Math.abs(A[p][j]))p=i;[A[j],A[p]]=[A[p],A[j]];if(Math.abs(A[j][j])<1e-12)throw Error('训练矩阵退化');let v=A[j][j];for(let k=j;k<=n;k++)A[j][k]/=v;for(let i=0;i<n;i++)if(i!==j){v=A[i][j];for(let k=j;k<=n;k++)A[i][k]-=v*A[j][k]}}return A.map(r=>r[n])}
function ridge(rows,features,outputs){const raw=rows.map(d=>features(d.x)),d=raw[0].length,mu=Array.from({length:d},(_,j)=>mean(raw.map(r=>r[j]))),sd=mu.map((m,j)=>Math.max(1e-8,Math.sqrt(mean(raw.map(r=>(r[j]-m)**2)))));const scale=x=>[1,...features(x).map((v,j)=>(v-mu[j])/sd[j])],X=rows.map(r=>scale(r.x)),A=Array.from({length:d+1},(_,j)=>Array.from({length:d+1},(_,k)=>sum(X.map(r=>r[j]*r[k]))+(j===k&&j>0?.01:0)));const coef=Array.from({length:outputs},(_,o)=>solve(A,Array.from({length:d+1},(_,j)=>sum(rows.map((r,i)=>X[i][j]*r.y[o])))));return {predict:x=>{const z=scale(x);return coef.map(c=>sum(c.map((v,j)=>v*z[j])))},coef,mu,sd}}
function batch(n,seed,make){const r=rng(seed);return Array.from({length:n},(_,i)=>make(r,i))}function mae(pred,truth){return mean(pred.map((p,i)=>Math.abs(p-truth[i])))}
const panel=(title,body)=>'<article class="panel"><h2>'+title+'</h2>'+body+'</article>';const plot=(title,body,desc='')=>'<article class="panel chart"><h2>'+title+'</h2>'+body+'<p class="small">'+desc+'</p></article>';

const features=x=>{let[q,d,e]=x;return [q,d,e,q*q,d*d,e*e,q*d,q*e]};function response(x){let[q,d,e]=x;return [72+15*q-3.6*q*q+10*(d-1.6)-21*e+3*q*e,26*d+1.9*q*q+7*e*q]}
function make(r){const x=[.5+2*r(),1.6+.4*r(),.8*r()],y=response(x).map((v,j)=>v+(r()-.5)*(j? .35:1.0));return {x,y}}const train=batch(240,17201,make),test=batch(60,27201,make),model=ridge(train,features,2);
function run(p={}){p=Object.assign({"ecc": 0.35, "pressureLimit": 54, "qmax": 2.4},p);const points=[];for(let i=0;i<21;i++)for(let j=0;j<17;j++){let x=[.5+i*.1,1.6+j*.025,p.ecc],y=model.predict(x),reasons=[];if(y[1]>p.pressureLimit)reasons.push('压力超过上限');if(x[0]>p.qmax+1e-9)reasons.push('排量超过泵量上限');points.push({id:points.length,x,eff:y[0],pressure:y[1],utility:y[0]-.4*x[0],reasons})}const feasible=points.filter(d=>!d.reasons.length),best=feasible.slice().sort((a,b)=>b.utility-a.utility)[0]||null;const x=[1.2,1.85,p.ecc],b=model.predict(x),baseline={x,eff:b[0],pressure:b[1],feasible:b[1]<=p.pressureLimit&&x[0]<=p.qmax};const metrics={efficiencyMAE:mae(test.map(d=>model.predict(d.x)[0]),test.map(d=>d.y[0])),pressureMAE:mae(test.map(d=>model.predict(d.x)[1]),test.map(d=>d.y[1])),denominator:60,candidates:points.length,feasible:feasible.length};return {params:p,points,best,baseline,metrics,summary:best?'357 个候选中 '+feasible.length+' 个满足条件；推荐排量 '+best.x[0].toFixed(2)+' m³/min、密度 '+best.x[1].toFixed(3)+' g/cm³。':'当前条件下没有可行候选；请查看压力窗口与泵量限制。',data:{kind:'固定种子教学响应面',train:240,test:60,seed:[17201,27201],units:['m³/min','g/cm³','偏心比例','效率 %','MPa']}}}
function describe(d){return '排量 '+d.x[0].toFixed(2)+' m³/min；密度 '+d.x[1].toFixed(3)+' g/cm³；效率 '+d.eff.toFixed(2)+'%；压力 '+d.pressure.toFixed(2)+' MPa；'+(d.reasons.join('，')||'满足全部约束')}
function render(r,h){const {n,svg,axes,circle,path,metric,table}=h;const pmin=40,pmax=Math.ceil(Math.max(r.params.pressureLimit,...r.points.map(d=>d.pressure))/5)*5,py=v=>258-(v-pmin)/(pmax-pmin)*236;let body=axes('排量 / m³/min','环空压力 / MPa',[.5,2.5],[pmin,pmax]);body+=r.points.map((d,i)=>circle(58+(d.x[0]-.5)/2*497,py(d.pressure),3.8,d.reasons.length?'#d5dad6':`hsl(${35+(d.eff-60)*2},45%,45%)`,'class="pick" data-pick="'+i+'"')).join('');const ly=py(r.params.pressureLimit);body+='<path d="M58 '+ly+'H555" stroke="#bb5d4a" stroke-dasharray="6 4"/>';if(r.best)body+=circle(58+(r.best.x[0]-.5)/2*497,py(r.best.pressure),8,'none','stroke="#162f36" stroke-width="3"');let slice=axes('排量 / m³/min','置换效率 / %',[.5,2.5],[40,100]);for(const [e,col] of [[0,'#267d78'],[r.params.ecc,'#c18b44'],[.8,'#bb5d4a']])slice+=path(Array.from({length:21},(_,i)=>{const q=.5+i*.1;return [58+i/20*497,258-(model.predict([q,1.85,e])[0]-40)/60*236]}),col);return '<div class="metric-grid">'+metric('可行候选',r.metrics.feasible,'/357 个')+metric('效率留出 MAE',n(r.metrics.efficiencyMAE),'百分点 · 60 样本')+metric('压力留出 MAE',n(r.metrics.pressureMAE),'MPa · 60 样本')+metric('推荐效率',r.best?n(r.best.eff):'无方案','%')+'</div><div class="charts">'+plot('先看压力边界，再看效率颜色',svg(body),'灰点不满足约束；彩点由橙黄（效率低）渐变为绿色（效率高），深色描边为推荐；红虚线是当前压力上限。点击任一点读取密度与排除原因。')+plot('同密度下，偏心怎样削弱置换？',svg(slice),'密度固定 1.85 g/cm³；绿色偏心 0、金色当前偏心、红色 0.8。曲线由已训练代理实际预测。')+'</div>'+panel('选中候选的条件','<p id="selection">'+(r.best?describe(r.best):'全部候选被约束排除。')+'</p>')+panel('固定方案接受相同条件检查',table(['方案','排量','密度','效率 / %','压力 / MPa','条件检查'],[[r.best?'推荐':'无可行推荐',r.best?n(r.best.x[0]):'—',r.best?n(r.best.x[1],3):'—',r.best?n(r.best.eff):'—',r.best?n(r.best.pressure):'—',r.best?'全部满足':'无推荐'],['固定基线',1.2,1.85,n(r.baseline.eff),n(r.baseline.pressure),r.baseline.feasible?'满足':'超限，不计为可行方案']]))}
g.CaseEngine={run,render,describe,model,response};})(globalThis);

